module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            IDLE: begin
                // Wait for in[3] to become 1
                if (in[3]) begin
                    next_state = BYTE1;
                    shift_reg  = {24{1'b0}}; // clear shift register
                end else begin
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Store first byte, move to BYTE2
                shift_reg = {in, 16'b0}; // in[7:0] goes to out_bytes[23:16]
                next_state = BYTE2;
            end

            BYTE2: begin
                // Store second byte, shift left by 8, move to BYTE3
                shift_reg = {shift_reg[15:0], in};
                next_state = BYTE3;
            end

            BYTE3: begin
                // Store third byte, complete the message
                shift_reg = {shift_reg[15:0], in};
                next_state = IDLE;
                done       = 1'b1; // assert done in the cycle after third byte
                out_bytes  = shift_reg;
            end
        endcase
    end

    // Sequential logic: state update and output registration on positive edge of clk
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            out_bytes <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            out_bytes <= shift_reg; // out_bytes valid when done is asserted
            done      <= 1'b0;      // done is a pulse, clear after being read (or keep asserted as per spec)
            // Note: The specification says "out_bytes needs to be valid whenever the done signal is asserted."
            // We keep out_bytes latched in shift_reg so it remains valid as long as done is high.
        end
    end

endmodule

