module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: 4-digit BCD
);

    // Internal register for the 4-digit BCD counter (16 bits)
    reg [15:0] q_reg;

    // Assign output ports
    assign q     = q_reg;
    assign ena   = {q_reg[15], q_reg[11], q_reg[7]}; // enable signals for upper three digits

    // Synchronous always block for counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // BCD increment logic
            // Step 1: Add 1 to the current value
            q_reg <= q_reg + 16'd1;

            // Step 2: BCD correction
            // If any 4-bit nibble is > 9 (i.e., 10-15), add 6 to fix it.
            // We check each nibble:
            // q_reg[3:0]   : ones
            // q_reg[7:4]   : tens
            // q_reg[11:8]  : hundreds
            // q_reg[15:12] : thousands

            // Correction logic: if a nibble is 10-15, add 6 (binary 0110)
            // We generate carry-enable signals for each digit

            // ones digit correction
            if (q_reg[3:0] > 4'd9) begin
                q_reg[3:0] <= q_reg[3:0] + 4'd6;
            end

            // tens digit correction (depends on ones overflow)
            if (q_reg[7:4] > 4'd9) begin
                q_reg[7:4] <= q_reg[7:4] + 4'd6;
            end

            // hundreds digit correction
            if (q_reg[11:8] > 4'd9) begin
                q_reg[11:8] <= q_reg[11:8] + 4'd6;
            end

            // thousands digit correction
            if (q_reg[15:12] > 4'd9) begin
                q_reg[15:12] <= q_reg[15:12] + 4'd6;
            end
        end
    end

endmodule

Prob150_review2015_fsmonehot.code:
module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded current state signals
    wire cur_S, cur_S1, cur_S11, cur_S110, cur_B0, cur_B1, cur_B2, cur_B3, cur_Count, cur_Wait;

    // One-hot decode: assign each state wire based on the state vector
    // Encoding: (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
    //           (10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000,
    //            10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000,
    //            10'b0100000000, 10'b1000000000)
    assign cur_S   = state[0];
    assign cur_S1  = state[1];
    assign cur_S11 = state[2];
    assign cur_S110= state[3];
    assign cur_B0  = state[4];
    assign cur_B1  = state[5];
    assign cur_B2  = state[6];
    assign cur_B3  = state[7];
    assign cur_Count = state[8];
    assign cur_Wait  = state[9];

    // ============================================
    // Next-state logic (one-hot output signals)
    // ============================================

    // B3_next: Assert when next-state is B3
    // From B2 (shift_ena=1) --always--> B3
    assign B3_next = cur_B2;

    // S_next: Assert when next-state is S
    // S  --d=0--> S
    // S110 --d=0--> S
    // Wait --ack=1--> S
    assign S_next  = (~d & cur_S) | (~d & cur_S110) | (ack & cur_Wait);

    // S1_next: Assert when next-state is S1
    // S  --d=1--> S1
    // The only transition listed targeting S1 is from S with d=1.
    assign S1_next = cur_S & d;

    // Count_next: Assert when next-state is Count
    // From B3 (shift_ena=1) --always--> Count
    assign Count_next = cur_B3;

    // Wait_next: Assert when next-state is Wait
    // From Count (counting=1) --done_counting=1--> Wait
    assign Wait_next = cur_Count & done_counting;

    // ============================================
    // Output logic
    // ============================================

    // shift_ena: Assert when in B0, B1, B2, B3 states
    assign shift_ena = cur_B0 | cur_B1 | cur_B2 | cur_B3;

    // counting: Assert when in Count state
    assign counting = cur_Count;

    // done: Assert when in Wait state (diagram: "Wait (done=1)")
    assign done = cur_Wait;

endmodule

