module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT,    // 000
        WALK_RIGHT,   // 001
        FALLING,      // 010
        DIGGING,      // 011
        SPLATTERED    // 100
    } state_t;

    // Registers
    state_t state, next_state;
    logic [1:0] walk_dir; // 00=left, 01=right - direction we're currently walking or last walked
    logic [4:0] fall_counter;
    logic [1:0] dir_before_fall_dig; // Direction before entering fall/dig

    // Outputs
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            walk_dir <= 2'b00;
            fall_counter <= 0;
            dir_before_fall_dig <= 2'b00;
        end else begin
            state <= next_state;
            // Update fall counter
            if (state == FALLING)
                fall_counter <= fall_counter + 1;
            else
                fall_counter <= 0;

            // Update walk_dir when changing to walking states
            if (next_state == WALK_LEFT || next_state == WALK_RIGHT)
                walk_dir <= (next_state == WALK_LEFT) ? 2'b00 : 2'b01;
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state;

        case (state)
            WALK_LEFT: begin
                if (!ground) begin
                    // Start falling, remember direction
                    next_state = FALLING;
                    dir_before_fall_dig <= 2'b00; // Was walking left
                end else if (dig) begin
                    next_state = DIGGING;
                    dir_before_fall_dig <= 2'b00; // Was walking left
                end else if (bump_right) begin
                    next_state = WALK_RIGHT;
                    walk_dir <= 2'b01; // Now walking right
                end else if (bump_left) begin
                    // Bumped on left, already walking left
                    // If also bumped right, switch
                    if (bump_right)
                        next_state = WALK_RIGHT;
                    // else stay WALK_LEFT
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    dir_before_fall_dig <= 2'b01; // Was walking right
                end else if (dig) begin
                    next_state = DIGGING;
                    dir_before_fall_dig <= 2'b01; // Was walking right
                end else if (bump_left) begin
                    next_state = WALK_LEFT;
                    walk_dir <= 2'b00; // Now walking left
                end else if (bump_right) begin
                    // Bumped on right, already walking right
                    if (bump_left)
                        next_state = WALK_LEFT;
                    // else stay WALK_RIGHT
                end
            end

            FALLING: begin
                if (ground) begin
                    if (fall_counter > 20) begin
                        // Splattered
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in remembered direction
                        if (dir_before_fall_dig == 2'b00)
                            next_state = WALK_LEFT;
                        else
                            next_state = WALK_RIGHT;
                    end
                end
                // If !ground, stay falling (counter already incrementing)
            end

            DIGGING: begin
                if (!ground) begin
                    // Fell while digging - remember was walking in dir_before_fall_dig
                    next_state = FALLING;
                    // dir_before_fall_dig already set when entering dig
                end else if (!dig) begin
                    // Stop digging - resume walking in original direction
                    if (dir_before_fall_dig == 2'b00)
                        next_state = WALK_LEFT;
                    else
                        next_state = WALK_RIGHT;
                end
                // else stay DIGGING
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
            end
        endcase
    end

endmodule

