module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // 2'b000: State A (reset/initial)
    // 2'b001: State B (f=1 pulse)
    // 2'b010: State C (monitoring x for 1,0,1)
    // 2'b011: State D (g=1, waiting for y=1 within 2 cycles)
    // 2'b100: State E (g=0 permanently)
    reg [1:0] state;
    reg [2:0] x_shift;  // Shift register to track x: 1,0,1 pattern
    reg [1:0] y_counter; // Counter to check y within 2 cycles
    reg f_reg, g_reg;

    // Output assignments
    assign f = f_reg;
    assign g = g_reg;

    // State transition and output logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state       <= 2'b00;
            x_shift     <= 3'b000;
            y_counter   <= 2'b00;
            f_reg       <= 1'b0;
            g_reg       <= 1'b0;
        end else begin
            // Defaults: keep outputs unless transition conditions met
            f_reg       <= 1'b0;
            g_reg       <= 1'b0;

            case (state)
                2'b00: begin // State A: reset/initial
                    // On de-assertion of reset, go to State B after next clock
                    // But spec says: "When reset signal is de-asserted, then after the next clock edge the FSM has to set the output f to 1 for one clock cycle."
                    // So on the first clock after reset de-assertion, f=1, then next state.
                    // We model this as: if resetn was just de-asserted, set f=1 and move to B.
                    // Since we don't have previous resetn, we assume immediate transition to B with f=1 on this edge.
                    state       <= 2'b01;
                    f_reg       <= 1'b1;
                    // x_shift and y_counter reset
                    x_shift     <= 3'b000;
                    y_counter   <= 2'b00;
                end
                2'b01: begin // State B: f=1 for one cycle, then monitor x
                    // f_reg already set to 1 in the block above for this cycle
                    // After this cycle, move to State C to start monitoring x
                    state       <= 2'b10; // Using 2'b10 for State C
                    f_reg       <= 1'b0;  // f pulse done
                end
                2'b10: begin // State C: monitor x for 1,0,1 pattern
                    // Shift x into x_shift
                    x_shift     <= {x_shift[1:0], x};

                    // Check if pattern 1,0,1 detected
                    if (x_shift == 3'b101) begin
                        state       <= 2'b11; // Move to State D
                        g_reg       <= 1'b1;  // Set g=1
                    end else begin
                        // Stay in State C, continue monitoring
                        // f_reg stays 0
                    end
                end
                2'b11: begin // State D: g=1, waiting for y=1 within 2 cycles
                    y_counter   <= y_counter + 1'b1;

                    // Check if y=1 within the counter limit
                    if (y == 1'b1) begin
                        // y=1 found within 2 cycles, maintain g=1
                        // Counter resets but g stays 1
                        y_counter <= 2'b00;
                        // state stays 2'b11
                    end else if (y_counter == 2'b10) begin
                        // Two cycles elapsed without y=1, set g=0 permanently
                        g_reg       <= 1'b0;
                        state       <= 2'b100; // Move to State E
                    end else begin
                        // Continue waiting
                    end
                end
                2'b100: begin // State E: g=0 permanently
                    g_reg       <= 1'b0;
                    // Stay in this state until reset
                end
            endcase
        end
    end

endmodule

