module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_synced;
    reg  [2:0] s_prev;
    reg  [1:0] state; // 00: above s2, 01: between s2 and s1, 10: between s1 and s0, 11: below s0
    reg        dfr_reg;

    // Synchronize inputs
    always @(posedge clk) begin
        if (reset) begin
            s_prev <= 3'b000;
            state  <= 2'b11; // below s0
            dfr_reg <= 1'b1;
        end else begin
            s_prev <= s;
            // Determine state based on current sensors
            if (s[2]) state <= 2'b00;       // Above s[2]
            else if (s[1]) state <= 2'b01;  // Between s[2] and s[1]
            else if (s[0]) state <= 2'b10;  // Between s[1] and s[0]
            else       state <= 2'b11;      // Below s[0]

            // dfr: Supplemental flow valve opens if previous level was lower than current level
            // "previous to the last sensor change" implies comparing current s with s_prev
            // If current level is higher (more sensors asserted) than previous, open dfr
            if (!s[2] && s_prev[2]) dfr_reg <= 1'b1; // Just came down from above s2
            else if (s[2] && !s_prev[2]) dfr_reg <= 1'b0; // Just went up from below s2
            else if (!s[1] && s_prev[1]) dfr_reg <= 1'b1; // Just came down from between s2-s1
            else if (s[1] && !s_prev[1]) dfr_reg <= 1'b0; // Just went up from between s2-s1
            else if (!s[0] && s_prev[0]) dfr_reg <= 1'b1; // Just came down from between s1-s0
            else if (s[0] && !s_prev[0]) dfr_reg <= 1'b0; // Just went up from below s0
            else dfr_reg <= dfr_reg; // Hold
        end
    end

    // Output assignments based on state and dfr
    assign fr0 = (state == 2'b10) || (state == 2'b11); // fr0 for between s1-s0 and below s0
    assign fr1 = (state == 2'b11);                       // fr1 only when below s0
    assign fr2 = (state == 2'b11);                       // fr2 only when below s0
    assign dfr = dfr_reg;

    // Active-high synchronous reset handling is inside the always block above
    // The reset state (2'b11, dfr_reg=1) corresponds to "below s0" with all outputs asserted.

endmodule
